 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            colors = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in colors:
                    colors[color] = [y, y, x, x]
                b = colors[color]
                b[0], b[1] = min(b[0], y), max(b[1], y)
                b[2], b[3] = min(b[2], x), max(b[3], x)
            order = sorted(colors, key=lambda color: -((colors[color][1]-colors[color][0]+1) * (colors[color][3]-colors[color][2]+1)))
            mapping = {color: order[-1-i] for i, color in enumerate(order)}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
